R.append((7722208,
("Hongo portobello relleno de espinacas y queso Wensleydale", "Este sombrero de hongo cubierto de espinacas y queso es una entrada o guarnición deliciosa y fácil de preparar.", "1", "348 g",
 ["1 cebolla pequeña, finamente picada", "1 cucharadita de aceite de oliva", "1 hongo portobello grande", "100 g de hojas de espinaca baby", "1 buena pizca de tomillo seco", "1 diente de ajo, machacado", "1 cucharadita de mostaza Dijon", "1 rebanada de pan integral, desmenuzada", "1 buena pizca de pimienta", "25 g de queso Wensleydale, cortado en cubos pequeños (o Cheddar, feta o queso de cabra)"],
 ["Precaliente el horno a 180 °C (gas 4).", "Ponga la cebolla en una sartén con el aceite y cocine hasta que esté bien dorada.", "Quite el tallo del hongo, píquelo y agréguelo a la cebolla junto con las espinacas, el tomillo y el ajo.", "Cuando las espinacas se hayan marchitado, agregue la mostaza, el pan y la pimienta, y mezcle bien. Tape y deje reposar un par de minutos para que el pan absorba todos los sabores.", "Vuelva a mezclar el relleno y colóquelo en montoncito sobre el sombrero del hongo.", "Espolvoree el queso de manera uniforme encima, presionándolo en el relleno, y hornee durante 10 minutos."],
 ["La espinaca congelada es un ingrediente útil para tener en el congelador. Busque hoja entera en lugar de picada y descongélela siempre antes de usarla para poder exprimir el exceso de agua.", "Las hojas de espinaca fresca son una excelente alternativa a la lechuga.", "Si no le gusta el queso Wensleydale, pruebe con la misma cantidad de Cheddar, feta o queso de cabra.", "Instrucciones para congelar: Congele con papel encerado entre cada hongo. Descongele durante 1 hora y luego caliente en el microondas o en un horno moderado.", "@FV"], []),
("فطر البورتوبيلو المحشو بالسبانخ وجبن ونسليديل", "غطاء الفطر هذا المغطى بالسبانخ والجبن يصنع مقبلات أو طبقًا جانبيًا لذيذًا وسهل التحضير.", "1", "348 جم",
 ["1 حبة بصل صغيرة، مفرومة ناعمًا", "1 ملعقة صغيرة زيت زيتون", "1 حبة فطر بورتوبيلو كبيرة", "100 جم أوراق سبانخ صغيرة", "رشة وافرة من الزعتر المجفف", "1 فص ثوم، مهروس", "1 ملعقة صغيرة خردل ديجون", "1 شريحة خبز قمح كامل، مفتتة", "رشة وافرة من الفلفل", "25 جم جبن ونسليديل، مقطع إلى مكعبات صغيرة (أو شيدر أو فيتا أو جبن الماعز)"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4).", "ضع البصل في مقلاة مع الزيت واطهه حتى يتحمر جيدًا.", "انزع ساق الفطر وقطّعها وأضفها إلى البصل مع السبانخ والزعتر والثوم.", "عندما تذبل السبانخ، أضف الخردل والخبز والفلفل واخلط جيدًا. غطِّ المقلاة واتركها دقيقتين حتى يمتص الخبز جميع النكهات.", "اخلط الحشوة مرة أخرى ثم كدّسها فوق غطاء الفطر.", "رش الجبن بالتساوي فوقها مع الضغط عليه في الحشوة، ثم اخبزها لمدة 10 دقائق."],
 ["السبانخ المجمدة مكوّن مفيد يُستحسن الاحتفاظ به في المجمد. ابحث عن السبانخ ذات الأوراق الكاملة بدلًا من المفرومة، وذوّبها دائمًا قبل الاستخدام حتى تتمكن من عصر الماء الزائد منها.", "أوراق السبانخ الطازجة بديل رائع للخس.", "إن كنت لا تحب جبن ونسليديل، فجرّب إضافة الكمية نفسها من الشيدر أو الفيتا أو جبن الماعز.", "تعليمات التجميد: جمّد الفطر مع وضع ورق الزبدة بين كل حبة وأخرى. ذوّبه لمدة ساعة واحدة، ثم سخّنه في الميكروويف أو في فرن معتدل الحرارة.", "@FV"], [])))
# 6
R.append((7724336,
("Arroz con leche de coco", "Una versión de arroz con leche con menos grasa.", "3", "204 g",
 ["100 g de arroz basmati", "400 ml de bebida de coco sin azúcar", "300 ml de leche de soya sin azúcar", "4 cucharaditas de edulcorante granulado", "unas gotas de esencia de vainilla", "1 cucharada de coco tostado"],
 ["Ponga todos los ingredientes, excepto el coco tostado, en una cacerola pequeña. Cocine a fuego bajo, a fuego muy lento, de 20 a 25 minutos, hasta que el arroz esté tierno.", "Sirva con el coco tostado por encima."],
 ["Cocine suavemente con la cacerola tapada; siempre puede agregar un poco más de leche de soya o agua si el arroz empieza a pegarse al fondo.", "Si no encuentra coco tostado, simplemente ponga 1 cucharada de coco rallado deshidratado en una sartén seca y revuelva a fuego medio de 2 a 3 minutos, hasta que empiece a dorarse."], []),
("بودنغ الأرز بجوز الهند", "نسخة أقل دسمًا من بودنغ الأرز.", "3", "204 جم",
 ["100 جم أرز بسمتي", "400 مل مشروب جوز الهند غير محلى", "300 مل حليب الصويا غير محلى", "4 ملاعق صغيرة محلي حبيبات", "بضع قطرات من خلاصة الفانيليا", "1 ملعقة كبيرة جوز هند محمص"],
 ["ضع جميع المكونات، عدا جوز الهند المحمص، في قدر صغير. ضعه على نار هادئة واتركه ينضج بلطف شديد لمدة 20–25 دقيقة حتى يلين الأرز.", "قدّمه مزيَّنًا بجوز الهند المحمص."],
 ["اطهه بلطف مع تغطية القدر؛ ويمكنك دائمًا إضافة قليل من حليب الصويا أو الماء إذا بدأ الأرز يلتصق بالقدر.", "إذا لم تجد جوز الهند المحمص، فما عليك سوى وضع 1 ملعقة كبيرة من جوز الهند المجفف المبشور في مقلاة جافة وتحريكه على نار متوسطة لمدة 2–3 دقائق حتى يبدأ بالتحمير."], [])))
# 7
R.append((7727187,
("Panecillos de Semana Santa extra frutales", "Estos panecillos de Semana Santa (hot cross buns) se preparan con harina integral y fruta adicional. Tienen todo el sabor tradicional y son saciantes y satisfactorios.", "12", "100 g",
 ["500 g de harina integral, más 1 cucharada para amasar", "1.5 cucharaditas (un sobre de 7 g) de levadura seca de acción rápida", "50 g de azúcar morena suave", "2 cucharaditas colmadas de mezcla de especias molidas (mixed spice)", "1 plátano maduro, hecho puré", "1 huevo, batido", "ralladura de 1 limón", "ralladura de 1 naranja", "1 manzana, sin el corazón y rallada, sin pelar", "200 ml de leche tibia", "125 g de fruta seca mixta", "2 cucharaditas de aceite de girasol"],
 ["Precaliente el horno a 190 °C (gas 5). Mezcle la harina, la levadura, el azúcar y la mezcla de especias en un tazón grande.", "En otro tazón, bata el plátano, el huevo, la ralladura de limón, la ralladura de naranja y la manzana.", "Incorpore poco a poco la leche tibia a la mezcla de harina con una cuchara de madera y luego integre la mezcla de huevo y plátano.", "Empiece a amasar esta masa pegajosa con una mano y luego vuélquela sobre una superficie de trabajo ligeramente enharinada. Estire y empuje la masa con la base de la palma de la mano, doblándola y espolvoreando un poco más de harina si se pega demasiado. Amase de 5 a 10 minutos, hasta que la masa esté suave y elástica.", "Aplane la masa, espolvoree con la fruta seca, dóblela y amase un par de minutos más hasta que la fruta seca quede integrada.", "Engrase ligeramente un tazón grande con una cucharadita de aceite, coloque la masa dentro, cubra con plástico adherente ligeramente engrasado y deje reposar en un lugar tibio durante 1 hora (un armario de aire caliente es ideal); debe duplicar su tamaño.", "Divida la masa en 12 panecillos redondos, acomódelos en una o dos charolas para hornear ligeramente engrasadas, dejando mucho espacio para que crezcan. Cubra de nuevo con plástico adherente o un paño de cocina limpio y deje reposar otra hora.", "Haga una cruz profunda en cada panecillo con un cuchillo afilado y hornee de 20 a 25 minutos, hasta que estén dorados."],
 ["Cómalos tibios, recién salidos del horno, o déjelos enfriar y guárdelos en un recipiente hermético de 2 a 3 días. Caliente los panecillos en el microondas, o pártalos y tuéstelos.", "Para agregar cruces blancas encima, mezcle de 50 a 60 g de harina con 2 cucharadas de agua hasta formar una pasta, extiéndala y córtela en tiras. Luego, humedezca con agua y pegue sobre los panecillos justo antes de meterlos al horno.", "Instrucciones para congelar: Se pueden congelar una vez cocidos. Congele en porciones envueltas individualmente para usarlas según las necesite. Descongele durante 2 horas, o en el microondas."], []),
("كعكات الصليب الساخنة (هوت كروس بنز) الغنية بالفاكهة", "تُحضَّر كعكات الصليب الساخنة هذه بدقيق القمح الكامل ومزيد من الفاكهة. وفيها كل النكهة التقليدية، وهي مشبعة ومرضية.", "12", "100 جم",
 ["500 جم دقيق القمح الكامل، إضافة إلى 1 ملعقة كبيرة للعجن", "1.5 ملعقة صغيرة (كيس 7 جم) خميرة جافة سريعة المفعول", "50 جم سكر بني ناعم", "2 ملعقة صغيرة مكوّمة من خليط التوابل المطحونة", "1 حبة موز ناضجة، مهروسة", "1 بيضة، مخفوقة", "قشر مبشور من ليمونة واحدة", "قشر مبشور من برتقالة واحدة", "1 حبة تفاح، منزوعة القلب ومبشورة دون تقشير", "200 مل حليب دافئ", "125 جم فاكهة مجففة مشكلة", "2 ملعقة صغيرة زيت عباد الشمس"],
 ["سخّن الفرن مسبقًا إلى 190° مئوية (درجة الغاز 5). اخلط الدقيق والخميرة والسكر وخليط التوابل معًا في وعاء كبير.", "في وعاء آخر، اخفق الموز والبيضة وقشر الليمون المبشور وقشر البرتقال والتفاح.", "أضف الحليب الدافئ تدريجيًا إلى خليط الدقيق مع التحريك بملعقة خشبية، ثم أضف خليط البيض والموز.", "ابدأ بعجن هذه العجينة اللزجة بيد واحدة، ثم أفرغها على سطح عمل مرشوش بقليل من الدقيق. مدّد العجينة وادفعها بكعب كفك، واطوها وارشَّ عليها المزيد من الدقيق قليلًا إذا التصقت كثيرًا. اعجنها لمدة 5–10 دقائق حتى تصبح ناعمة ومرنة.", "افرد العجينة ورش عليها الفاكهة المجففة، ثم اطوها واعجنها دقيقتين إضافيتين حتى تتخلل الفاكهة المجففة العجين.", "ادهن وعاءً كبيرًا بقليل من الزيت باستخدام ملعقة صغيرة منه، وضع العجينة في الوعاء، وغطّه بغلاف بلاستيكي مدهون بقليل من الزيت واتركها لتتخمر في مكان دافئ لمدة ساعة واحدة (خزانة التجفيف الدافئة مثالية)، ويجب أن يتضاعف حجمها.", "قسّم العجينة إلى 12 كعكة مستديرة ورتّبها على صينية أو صينيتي خبز مدهونتين بقليل من الزيت، مع ترك مساحة واسعة لتتمدد. غطّها مرة أخرى بغلاف بلاستيكي أو بمنشفة مطبخ نظيفة واتركها لتتخمر ساعة أخرى.", "اصنع علامة صليب عميقة على كل كعكة بسكين حاد، ثم اخبزها لمدة 20–25 دقيقة حتى يصبح لونها بنيًا ذهبيًا."],
 ["تناولها دافئة من الفرن، أو اتركها لتبرد واحفظها في وعاء محكم الإغلاق لمدة 2–3 أيام. سخّن الكعكات في الميكروويف، أو اشقّها واحمّصها.", "لإضافة صلبان بيضاء على الوجه، اخلط 50–60 جم من الدقيق مع 2 ملعقة كبيرة من الماء لتكوين عجينة، ثم مدّدها وقطّعها إلى شرائح. بعد ذلك، بلّلها بالماء والصقها على الكعكات قبل إدخالها الفرن مباشرة.", "تعليمات التجميد: مناسبة للتجميد بعد الطهي. جمّدها في حصص ملفوفة فرديًا لاستخدامها عند الحاجة. ذوّبها لمدة ساعتين، أو في الميكروويف."], [])))
